-- 459_intake_xjz_csharp_evidence_source_index.sql
-- Purpose: ingest C# restored evidence source index without exposing hashes or raw JSON notes.
-- Source pack: XJZ-csharp-evidence-capture-pack-20260818.zip

DROP TABLE IF EXISTS god2_research._xjz_stage_evidence_source;
DROP TABLE IF EXISTS god2_research._xjz_stage_client_evidence_file;

CREATE TABLE god2_research._xjz_stage_evidence_source (
  id INT PRIMARY KEY,
  source_path VARCHAR(255) NOT NULL,
  source_line INT NULL,
  source_key VARCHAR(128) NULL,
  evidence_status VARCHAR(96) NOT NULL,
  packet_evidence_boundary INT NOT NULL,
  note LONGTEXT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE god2_research._xjz_stage_client_evidence_file (
  id INT PRIMARY KEY,
  relative_path VARCHAR(255) NOT NULL,
  extension VARCHAR(32) NOT NULL,
  size_bytes BIGINT NOT NULL,
  sha1_head VARCHAR(64) NOT NULL,
  readable_csv INT NOT NULL,
  csv_rows_total INT NULL,
  declared_count INT NULL,
  header_line INT NULL,
  field_count INT NULL,
  header_preview TEXT NULL,
  category VARCHAR(96) NOT NULL,
  server_table_hint TEXT NOT NULL,
  evidence_status VARCHAR(96) NOT NULL,
  packet_evidence_boundary INT NOT NULL,
  indexed_at VARCHAR(32) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


CREATE TABLE IF NOT EXISTS god2_research.xjz_csharp_evidence_sources (
  source_id INT NOT NULL,
  source_path_zh_tw VARCHAR(255) NOT NULL,
  source_line INT NULL,
  source_key_zh_tw VARCHAR(128) NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  PRIMARY KEY (source_id),
  KEY ix_xjz_csharp_evidence_source_key (source_key_zh_tw)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='C#證據包：客戶端證據來源索引，不保留雜湊或原始JSON備註。';

CREATE TABLE IF NOT EXISTS god2_research.xjz_csharp_client_evidence_files (
  file_id INT NOT NULL,
  relative_path_zh_tw VARCHAR(255) NOT NULL,
  extension_zh_tw VARCHAR(32) NOT NULL,
  size_bytes BIGINT NOT NULL,
  readable_csv INT NOT NULL,
  csv_rows_total INT NULL,
  declared_count INT NULL,
  header_line INT NULL,
  field_count INT NULL,
  category_zh_tw VARCHAR(128) NOT NULL,
  server_table_hint_zh_tw TEXT NOT NULL,
  evidence_status_zh_tw VARCHAR(96) NOT NULL,
  needs_packet_evidence INT NOT NULL,
  indexed_at_text VARCHAR(32) NULL,
  PRIMARY KEY (file_id),
  UNIQUE KEY ux_xjz_csharp_client_file_path (relative_path_zh_tw),
  KEY ix_xjz_csharp_client_file_category (category_zh_tw)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
COMMENT='C#證據包：客戶端檔案索引，保留分類與服務端表提示。';

DELETE FROM god2_research.xjz_csharp_evidence_sources;
SELECT id, source_path, source_line, source_key, evidence_status, packet_evidence_boundary
FROM god2_research._xjz_stage_evidence_source;

DELETE FROM god2_research.xjz_csharp_client_evidence_files;
SELECT
  id,
  relative_path,
  extension,
  size_bytes,
  readable_csv,
  csv_rows_total,
  declared_count,
  header_line,
  field_count,
  CASE category
    WHEN 'quest' THEN '任務'
    WHEN 'npc_dialog' THEN 'NPC對話'
    WHEN 'skill_effect' THEN '技能效果'
    WHEN 'item_function' THEN '道具功能'
    WHEN 'god' THEN '神仙'
    WHEN 'audio_visual' THEN '影音外觀'
    WHEN 'combat_pet' THEN '戰寵'
    WHEN 'client_config' THEN '客戶端設定'
    WHEN 'monster' THEN '怪物'
    WHEN 'mount_transport' THEN '坐騎傳送'
    WHEN 'achievement' THEN '成就'
    ELSE category END,
  server_table_hint,
  evidence_status,
  packet_evidence_boundary,
  indexed_at
FROM god2_research._xjz_stage_client_evidence_file;

CREATE OR REPLACE VIEW god2_research.vw_xjz_csharp_evidence_source_index_summary_zh_tw AS
SELECT '證據來源' AS 資料類型, COUNT(*) AS 筆數, SUM(needs_packet_evidence) AS 需要封包證據, NULL AS 可讀CSV, NULL AS 分類數
FROM god2_research.xjz_csharp_evidence_sources
UNION ALL
SELECT '客戶端檔案索引', COUNT(*), SUM(needs_packet_evidence), SUM(readable_csv), COUNT(DISTINCT category_zh_tw)
FROM god2_research.xjz_csharp_client_evidence_files;

CREATE OR REPLACE VIEW god2_research.vw_xjz_csharp_client_evidence_file_categories_zh_tw AS
SELECT category_zh_tw AS 證據分類, COUNT(*) AS 檔案數, SUM(needs_packet_evidence) AS 需要封包證據, SUM(readable_csv) AS 可讀CSV數
FROM god2_research.xjz_csharp_client_evidence_files
GROUP BY category_zh_tw;

UPDATE god2_research.xjz_csharp_zip_evidence_digest
SET current_project_status_zh_tw = '已匯入客戶端證據來源索引',
    safe_apply_level_zh_tw = '可用於所有後續功能追溯，不直接改 runtime',
    next_server_action_zh_tw = '後續每批功能提升正式表前，先回查此來源索引確認證據路徑、分類與是否需要封包證據。',
    blocked_reason_zh_tw = NULL,
    related_project_object_zh_tw = 'migration 459, xjz_csharp_evidence_sources, xjz_csharp_client_evidence_files'
WHERE evidence_key = 'evidence_source_index';

DROP TABLE IF EXISTS god2_research._xjz_stage_evidence_source;
DROP TABLE IF EXISTS god2_research._xjz_stage_client_evidence_file;